CREATE OR REPLACE FUNCTION public.atlas_geography_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE subject atlas_entities%ROWTYPE; level integer; parent_level integer; manifest json; data jsonb;
BEGIN
 IF TG_TABLE_NAME='atlas_geographic_releases' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'staged' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic release must begin staged'; END IF;
   IF (SELECT status FROM atlas_sources WHERE id=NEW.source_id) IS DISTINCT FROM 'reference' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic release requires a reference source'; END IF;
   manifest:=NEW.expected_counts::json;
   IF (SELECT count(*) FROM pg_catalog.json_each(manifest))<>6 OR EXISTS(SELECT 1 FROM json_each(NEW.expected_counts) c WHERE c.key NOT IN ('location','province','area','region','subcontinent','continent') OR c.type<>'integer' OR c.value::numeric<0 OR c.value::numeric>9007199254740991) OR json_extract(NEW.expected_counts,'$.continent') IS DISTINCT FROM '6' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Release manifest requires six tiers and six continents'; END IF;
  ELSE
   PERFORM pg_advisory_xact_lock(hashtextextended('geography-release:'||NEW.id,0));
   PERFORM pg_advisory_xact_lock(hashtextextended('geography-published-version',0));
   IF OLD.status='published' OR NEW.status<>'published' OR (to_jsonb(NEW)-'status'-'published_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'published_at') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic release definitions are immutable'; END IF;
   IF EXISTS(SELECT 1 FROM atlas_geographic_releases WHERE status='published' AND version>=NEW.version) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Published release versions must advance'; END IF;
   IF EXISTS(SELECT 1 FROM json_each(NEW.expected_counts) c WHERE c.value::numeric<>(SELECT count(*) FROM atlas_geographic_memberships m JOIN atlas_entities e ON e.id=m.entity_id WHERE m.release_id=NEW.id AND m.active=1 AND e.kind=c.key)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic release manifest count mismatch'; END IF;
   IF EXISTS(SELECT 1 FROM atlas_geographic_memberships m JOIN atlas_entities e ON e.id=m.entity_id LEFT JOIN atlas_geographic_memberships p ON p.release_id=m.release_id AND p.entity_id=m.parent_id AND p.active=1 WHERE m.release_id=NEW.id AND m.active=1 AND e.kind<>'continent' AND p.entity_id IS NULL) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Incomplete active reference parent chain'; END IF;
   IF EXISTS(SELECT 1 FROM atlas_geographic_memberships m JOIN atlas_entities e ON e.id=m.entity_id WHERE m.release_id=NEW.id AND m.active=1 AND e.kind<>'location' AND NOT EXISTS(SELECT 1 FROM atlas_geographic_memberships c WHERE c.release_id=m.release_id AND c.parent_id=m.entity_id AND c.active=1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active geographic group has no member territory'; END IF;
   IF EXISTS(SELECT 1 FROM atlas_geographic_changes c LEFT JOIN atlas_geographic_memberships n ON n.release_id=c.release_id AND n.entity_id=c.new_entity_id AND n.active=1 LEFT JOIN atlas_geographic_memberships o ON o.release_id=c.release_id AND o.entity_id=c.old_entity_id AND o.active=1 WHERE c.release_id=NEW.id AND ((c.new_entity_id IS NOT NULL AND n.entity_id IS NULL) OR (c.change_type IN ('merge','split','replace','retire') AND o.entity_id IS NOT NULL))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic crosswalk must agree with active reference membership'; END IF;
  END IF;
 ELSE
  PERFORM pg_advisory_xact_lock(hashtextextended('geography-release:'||NEW.release_id,0));
  IF (SELECT status FROM atlas_geographic_releases WHERE id=NEW.release_id) IS DISTINCT FROM 'staged' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Published geographic memberships and crosswalks are immutable'; END IF;
  IF (SELECT status FROM atlas_sources WHERE id=NEW.source_id) IS DISTINCT FROM 'reference' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reference geography requires a reference source'; END IF;
  IF TG_TABLE_NAME='atlas_geographic_memberships' THEN
   SELECT e.* INTO subject FROM atlas_entities e WHERE e.id=NEW.entity_id;
   SELECT geographic_level INTO level FROM atlas_entity_types WHERE id=subject.kind;
   IF subject.is_example<>0 OR level IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Membership requires a non-example geographic identity'; END IF;
   SELECT t.geographic_level INTO parent_level FROM atlas_entities p JOIN atlas_entity_types t ON t.id=p.kind WHERE p.id=NEW.parent_id AND p.is_example=0;
   IF level=5 AND NEW.parent_id IS NOT NULL OR level<5 AND (NEW.parent_id IS NULL OR parent_level IS DISTINCT FROM level+1) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reference membership must use an adjacent-tier parent'; END IF;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM pg_catalog.json_each(NEW.evidence::json)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic change requires explicit source evidence'; END IF;
   IF EXISTS(SELECT 1 FROM atlas_entities e LEFT JOIN atlas_entity_types t ON t.id=e.kind WHERE e.id IN (NEW.old_entity_id,NEW.new_entity_id) AND (e.is_example<>0 OR t.geographic_level IS NULL)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Crosswalk requires non-example geographic identities'; END IF;
   IF NEW.old_entity_id IS NOT NULL AND NEW.new_entity_id IS NOT NULL AND (SELECT kind FROM atlas_entities WHERE id=NEW.old_entity_id) IS DISTINCT FROM (SELECT kind FROM atlas_entities WHERE id=NEW.new_entity_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic crosswalk endpoints must stay in tier'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior jsonb; incoming jsonb; identity text; keys text[];
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Evidence and identities are append-only: '||TG_TABLE_NAME; END IF;
 incoming:=to_jsonb(NEW);
 IF TG_TABLE_NAME='atlas_geographic_memberships' THEN
  identity:=NEW.release_id||'/'||NEW.entity_id;
  EXECUTE format('SELECT to_jsonb(r) FROM %I r WHERE release_id=$1 AND entity_id=$2',TG_TABLE_NAME) INTO prior USING NEW.release_id,NEW.entity_id;
 ELSE
  identity:=NEW.id;
 END IF;
 IF NOT atlas_nonblank(identity) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid stable ID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(TG_TABLE_NAME||':'||identity,0));
 IF TG_TABLE_NAME='atlas_geographic_memberships' THEN
  EXECUTE format('SELECT to_jsonb(r) FROM %I r WHERE release_id=$1 AND entity_id=$2',TG_TABLE_NAME) INTO prior USING NEW.release_id,NEW.entity_id;
 ELSE
  EXECUTE format('SELECT to_jsonb(r) FROM %I r WHERE id=$1',TG_TABLE_NAME) INTO prior USING NEW.id;
 END IF;
 IF TG_TABLE_NAME='atlas_ingestions' THEN incoming:=incoming-'rowid'-'created_at'; prior:=prior-'rowid'-'created_at'; END IF;
 IF TG_TABLE_NAME='atlas_geographic_releases' THEN incoming:=incoming-'status'-'published_at'; prior:=prior-'status'-'published_at'; END IF;
 IF prior IS NOT NULL THEN
  IF prior IS DISTINCT FROM incoming THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stable ID collision: '||TG_TABLE_NAME; END IF;
  RETURN NULL; -- Identical retry never rewrites original bytes or timestamps.
 END IF;
 FOR identity IN SELECT unnest(CASE TG_TABLE_NAME
  WHEN 'atlas_sources' THEN ARRAY['name','license','vintage']
  WHEN 'atlas_entity_types' THEN ARRAY['name'] WHEN 'atlas_entities' THEN ARRAY['name']
  WHEN 'atlas_categories' THEN ARRAY['name'] WHEN 'atlas_names' THEN ARRAY['name','language','role']
  WHEN 'atlas_relationships' THEN ARRAY['relationship_type']
  WHEN 'atlas_media' THEN ARRAY['name','license','attribution','mime']
  WHEN 'atlas_media_links' THEN ARRAY['role']
  WHEN 'atlas_evidence_retirements' THEN ARRAY['target_id','reason'] ELSE ARRAY[]::text[] END)
 LOOP IF NOT atlas_nonblank(incoming->>identity) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Empty source or identity text'; END IF; END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_json_at(value text, path text DEFAULT '$'::text)
 RETURNS json
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE keys text[];
BEGIN
 IF path='$' THEN RETURN value::json; END IF;
 IF left(path,2)<>'$.' THEN RAISE EXCEPTION 'Unsupported atlas JSON path'; END IF;
 keys:=string_to_array(substr(path,3),'.'); RETURN value::json #> keys;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_temporal_existence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM atlas_temporal_geography_validations WHERE id=NEW.validation_id) AND NOT EXISTS(SELECT 1 FROM atlas_geographic_existence_records WHERE id=NEW.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Temporal validation receipt is sealed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM atlas_geographic_memberships m JOIN atlas_entities e ON e.id=m.entity_id JOIN atlas_entity_types t ON t.id=e.kind WHERE m.release_id=NEW.release_id AND m.entity_id=NEW.entity_id AND m.active=1 AND t.geographic_level IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Claim requires an approved geographic identity'; END IF;
 IF EXISTS(SELECT 1 FROM atlas_sources s WHERE s.id=NEW.source_id AND (NEW.valid_from<s.supported_from OR NEW.valid_to>s.supported_to OR (s.status='example' AND NEW.is_example=0) OR s.status='estimate' OR (s.status='reference' AND NEW.method<>'reference'))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported geographic source interval/class'; END IF;
 IF EXISTS(SELECT 1 FROM atlas_entities e WHERE e.id=NEW.entity_id AND ((e.valid_from IS NOT NULL AND NEW.valid_from<e.valid_from) OR (e.valid_to IS NOT NULL AND NEW.valid_to>e.valid_to) OR (e.is_example=1 AND NEW.is_example=0))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Claim exceeds identity lifetime/example isolation'; END IF;
 IF NOT EXISTS(SELECT 1 FROM atlas_temporal_geography_retirements WHERE collection='existence' AND target_id=NEW.id) AND EXISTS(SELECT 1 FROM atlas_geographic_existence_records r WHERE r.id<>NEW.id AND r.release_id=NEW.release_id AND r.entity_id=NEW.entity_id AND r.method=NEW.method AND r.is_example=NEW.is_example AND r.valid_from<NEW.valid_to AND r.valid_to>NEW.valid_from AND NOT EXISTS(SELECT 1 FROM atlas_temporal_geography_retirements t WHERE t.collection='existence' AND t.target_id=r.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Overlapping equal-precedence geographic claims'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_temporal_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous jsonb; incoming jsonb:=to_jsonb(NEW);
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Temporal evidence is append-only'; END IF;
 PERFORM pg_advisory_xact_lock(807245315,1);
 EXECUTE format('SELECT to_jsonb(r) FROM %I r WHERE id=$1',TG_TABLE_NAME) INTO previous USING NEW.id;
 IF TG_TABLE_NAME='atlas_temporal_geography_validations' THEN previous:=previous-'created_at'; incoming:=incoming-'created_at'; END IF;
 IF previous IS NOT NULL THEN IF previous IS DISTINCT FROM incoming THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stable temporal identity collision'; END IF; RETURN NULL; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_temporal_memberships_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM atlas_temporal_geography_validations WHERE id=NEW.validation_id) AND NOT EXISTS(SELECT 1 FROM atlas_geographic_membership_records WHERE id=NEW.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Temporal validation receipt is sealed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM atlas_geographic_memberships m JOIN atlas_entities e ON e.id=m.entity_id JOIN atlas_entity_types t ON t.id=e.kind WHERE m.release_id=NEW.release_id AND m.entity_id=NEW.entity_id AND m.active=1 AND t.geographic_level IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Claim requires an approved geographic identity'; END IF;
 IF EXISTS(SELECT 1 FROM atlas_sources s WHERE s.id=NEW.source_id AND (NEW.valid_from<s.supported_from OR NEW.valid_to>s.supported_to OR (s.status='example' AND NEW.is_example=0) OR s.status='estimate' OR (s.status='reference' AND NEW.method<>'reference'))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported geographic source interval/class'; END IF;
 IF EXISTS(SELECT 1 FROM atlas_entities e WHERE e.id=NEW.entity_id AND ((e.valid_from IS NOT NULL AND NEW.valid_from<e.valid_from) OR (e.valid_to IS NOT NULL AND NEW.valid_to>e.valid_to) OR (e.is_example=1 AND NEW.is_example=0))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Claim exceeds identity lifetime/example isolation'; END IF;
 IF NOT EXISTS(SELECT 1 FROM atlas_temporal_geography_retirements WHERE collection='memberships' AND target_id=NEW.id) AND EXISTS(SELECT 1 FROM atlas_geographic_membership_records r WHERE r.id<>NEW.id AND r.release_id=NEW.release_id AND r.entity_id=NEW.entity_id AND r.method=NEW.method AND r.is_example=NEW.is_example AND r.valid_from<NEW.valid_to AND r.valid_to>NEW.valid_from AND NOT EXISTS(SELECT 1 FROM atlas_temporal_geography_retirements t WHERE t.collection='memberships' AND t.target_id=r.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Overlapping equal-precedence geographic claims'; END IF;
 IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM atlas_entities e JOIN atlas_entity_types et ON et.id=e.kind JOIN atlas_geographic_memberships p ON p.release_id=NEW.release_id AND p.entity_id=NEW.parent_id AND p.active=1 JOIN atlas_entities pe ON pe.id=p.entity_id JOIN atlas_entity_types pt ON pt.id=pe.kind WHERE e.id=NEW.entity_id AND pt.geographic_level=et.geographic_level+1 AND (NEW.is_example=1 OR pe.is_example=0) AND (pe.valid_from IS NULL OR NEW.valid_from>=pe.valid_from) AND (pe.valid_to IS NULL OR NEW.valid_to<=pe.valid_to)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Parent must be an approved adjacent-tier identity within its lifetime'; END IF;
 IF EXISTS(SELECT 1 FROM atlas_entities WHERE id=NEW.entity_id AND kind='continent') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Continents cannot acquire dated parents'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_temporal_retirements_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM atlas_temporal_geography_validations WHERE id=NEW.validation_id) AND NOT EXISTS(SELECT 1 FROM atlas_temporal_geography_retirements WHERE id=NEW.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Temporal validation receipt is sealed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM (SELECT id,entity_id,release_id,valid_from,valid_to,is_example FROM atlas_geographic_membership_records WHERE NEW.collection='memberships' UNION ALL SELECT id,entity_id,release_id,valid_from,valid_to,is_example FROM atlas_geographic_existence_records WHERE NEW.collection='existence') c WHERE c.id=NEW.target_id AND c.release_id=NEW.release_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Retired geographic claim must exist in the same release'; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT id,entity_id,release_id,valid_from,valid_to,is_example FROM atlas_geographic_membership_records WHERE NEW.collection='memberships' UNION ALL SELECT id,entity_id,release_id,valid_from,valid_to,is_example FROM atlas_geographic_existence_records WHERE NEW.collection='existence') c JOIN atlas_sources s ON s.id=NEW.source_id WHERE c.id=NEW.target_id AND ((s.status='example' AND c.is_example=0) OR s.supported_from>c.valid_from OR s.supported_to<c.valid_to)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Withdrawal source must support the target interval and factual status'; END IF;
 IF EXISTS(WITH RECURSIVE chain(id) AS (SELECT NEW.replacement_id WHERE NEW.replacement_id IS NOT NULL UNION SELECT t.replacement_id FROM atlas_temporal_geography_retirements t JOIN chain c ON t.target_id=c.id WHERE t.collection=NEW.collection AND t.replacement_id IS NOT NULL) SELECT 1 FROM chain WHERE id=NEW.target_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Geographic supersession cycle'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.atlas_temporal_validations_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM atlas_ingestions WHERE id=NEW.ingestion_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Temporal validation must precede a new tracked ingestion'; END IF;
 IF NOT EXISTS(SELECT 1 FROM atlas_geographic_releases r WHERE r.id=NEW.release_id AND r.status='published' AND r.hierarchy_sha256=NEW.hierarchy_sha256 AND r.footprints_sha256=NEW.footprints_sha256 AND NOT EXISTS(SELECT 1 FROM atlas_geographic_releases newer WHERE newer.status='published' AND newer.version>r.version)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Published geography does not match transaction pins'; END IF;
 IF EXISTS(SELECT 1 FROM atlas_temporal_geography_retirements t WHERE t.validation_id=NEW.id AND t.replacement_id IS NOT NULL AND ((t.collection='memberships' AND NOT EXISTS(SELECT 1 FROM atlas_geographic_membership_records r WHERE r.id=t.replacement_id AND r.release_id=t.release_id)) OR (t.collection='existence' AND NOT EXISTS(SELECT 1 FROM atlas_geographic_existence_records r WHERE r.id=t.replacement_id AND r.release_id=t.release_id)))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Replacement geographic claim is missing'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.json_each(input_json text, path text DEFAULT '$'::text)
 RETURNS TABLE(key text, value text, type text)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE item json;
BEGIN
 item:=atlas_json_at(input_json,path);
 IF json_typeof(item)='object' THEN RETURN QUERY SELECT p.key,p.value #>> '{}',json_type(p.value::text) FROM pg_catalog.json_each(item) p;
 ELSIF json_typeof(item)='array' THEN RETURN QUERY SELECT (p.ordinality-1)::text,p.value #>> '{}',json_type(p.value::text) FROM json_array_elements(item) WITH ORDINALITY p(value,ordinality);
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.json_type(value text, path text DEFAULT '$'::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE item json; kind text; token text;
BEGIN
 item:=atlas_json_at(value,path); IF item IS NULL THEN RETURN NULL; END IF;
 kind:=json_typeof(item); token:=btrim(item::text,E' \t\n\r');
 IF kind='string' THEN RETURN 'text'; END IF;
 IF kind='number' THEN RETURN CASE WHEN token ~ '^-?(0|[1-9][0-9]*)$' THEN 'integer' ELSE 'real' END; END IF;
 IF kind='boolean' THEN RETURN token; END IF;
 RETURN kind;
END $function$

CREATE OR REPLACE FUNCTION public.worldatlas_membership_copy_batch(payload json)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE copied integer;
BEGIN
 IF json_typeof(payload)<>'array' OR json_array_length(payload)>200 OR octet_length(payload::text)>8388608 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Owner membership copy exceeds bounded page';
 END IF;
 INSERT INTO public.worldatlas_membership_release_keys(id)
  SELECT DISTINCT x.release_id FROM json_to_recordset(payload) x(release_id text) ON CONFLICT DO NOTHING;
 INSERT INTO public.worldatlas_membership_entity_keys(id)
  SELECT x.entity_id FROM json_to_recordset(payload) x(entity_id text)
  UNION SELECT x.parent_id FROM json_to_recordset(payload) x(parent_id text) WHERE x.parent_id IS NOT NULL
  ON CONFLICT DO NOTHING;
 INSERT INTO public.worldatlas_membership_source_keys(id)
  SELECT DISTINCT x.source_id FROM json_to_recordset(payload) x(source_id text) ON CONFLICT DO NOTHING;
 INSERT INTO public.worldatlas_membership_evidence(digest,raw)
  SELECT DISTINCT sha256(convert_to(x.evidence,'UTF8')),x.evidence FROM json_to_recordset(payload) x(evidence text)
  ON CONFLICT DO NOTHING;
 IF EXISTS(SELECT 1 FROM json_to_recordset(payload) x(evidence text)
  JOIN public.worldatlas_membership_evidence e ON e.digest=sha256(convert_to(x.evidence,'UTF8'))
  WHERE e.raw IS DISTINCT FROM x.evidence COLLATE "C") THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Evidence digest collision or changed original bytes';
 END IF;
 INSERT INTO public.worldatlas_membership_rows
 SELECT r.key,e.key,p.key,x.reference_name,x.active,s.key,v.key
 FROM json_to_recordset(payload) x(release_id text,entity_id text,parent_id text,reference_name text,active integer,source_id text,evidence text)
 JOIN public.worldatlas_membership_release_keys r ON r.id=x.release_id
 JOIN public.worldatlas_membership_entity_keys e ON e.id=x.entity_id
 LEFT JOIN public.worldatlas_membership_entity_keys p ON p.id=x.parent_id
 JOIN public.worldatlas_membership_source_keys s ON s.id=x.source_id
 JOIN public.worldatlas_membership_evidence v ON v.digest=sha256(convert_to(x.evidence,'UTF8'));
 GET DIAGNOSTICS copied=ROW_COUNT;
 IF copied<>json_array_length(payload) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Incomplete owner membership copy'; END IF;
 RETURN copied;
END $function$

CREATE OR REPLACE FUNCTION public.worldatlas_membership_save(release_id text, entity_id text, parent_id text, reference_name text, active integer, source_id text, evidence text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE release_key integer; entity_key integer; parent_key integer; source_key integer;
 evidence_key integer; raw_original text; evidence_digest bytea;
BEGIN
 INSERT INTO public.worldatlas_membership_release_keys(id) VALUES(release_id) ON CONFLICT DO NOTHING;
 SELECT k.key INTO release_key FROM public.worldatlas_membership_release_keys k WHERE k.id=release_id;
 INSERT INTO public.worldatlas_membership_entity_keys(id) VALUES(entity_id) ON CONFLICT DO NOTHING;
 SELECT k.key INTO entity_key FROM public.worldatlas_membership_entity_keys k WHERE k.id=entity_id;
 IF parent_id IS NOT NULL THEN
  INSERT INTO public.worldatlas_membership_entity_keys(id) VALUES(parent_id) ON CONFLICT DO NOTHING;
  SELECT k.key INTO parent_key FROM public.worldatlas_membership_entity_keys k WHERE k.id=parent_id;
 END IF;
 INSERT INTO public.worldatlas_membership_source_keys(id) VALUES(source_id) ON CONFLICT DO NOTHING;
 SELECT k.key INTO source_key FROM public.worldatlas_membership_source_keys k WHERE k.id=source_id;
 evidence_digest:=pg_catalog.sha256(pg_catalog.convert_to(evidence,'UTF8'));
 INSERT INTO public.worldatlas_membership_evidence(digest,raw) VALUES(evidence_digest,evidence) ON CONFLICT DO NOTHING;
 SELECT k.key,k.raw INTO evidence_key,raw_original FROM public.worldatlas_membership_evidence k WHERE k.digest=evidence_digest;
 IF raw_original IS DISTINCT FROM evidence COLLATE "C" THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Evidence digest collision or changed original bytes';
 END IF;
 INSERT INTO public.worldatlas_membership_rows VALUES(release_key,entity_key,parent_key,reference_name,active,source_key,evidence_key);
END $function$
